    string QuoteFeedback(PlacementQuote quote){var previous=_movingProject is {} id?_sim.State.Projects.FirstOrDefault(p=>p.Id==id):null;var usable=_sim.Available+(previous?.BudgetRemaining??0)-decimal.Round(previous?.CrewCostDue??0,2,MidpointRounding.AwayFromZero);return quote.PhysicallyValid&&quote.Total>usable?"Saldo insuficiente · disponível "+Cash(Math.Max(0,usable))+" · falta "+Cash(quote.Total-usable):quote.Message+(quote.MachineryEstimate>0?" · máquinas e operadores externos incluídos: "+Cash(quote.MachineryEstimate):"");}
