    void RefreshInspection()
    {
        if(_inspection==null)return;var s=_sim.State;var selected=s.Buildings.FirstOrDefault(b=>b.Id==_selectedBuilding&&!b.Removed);var project=s.Projects.FirstOrDefault(p=>p.Id==(_selectedProject??selected?.ProjectId));var key=$"{_cityId}:{_selectedBuilding}:{_selectedProject}:{_selectedCitizen}:{_selectedVehicle}:{_selectedRoad}:{s.NextId}:{s.RoadRevision}:{selected?.Completed}:{selected?.CompanyId}:{selected?.FamilyId}:{selected?.Demolition!=null}:{project?.Status}:"+string.Join(",",s.Citizens.Where(c=>c.Alive&&c.WorkplaceId==_selectedBuilding).Select(c=>c.Id));
        if(key==_inspectionKey){foreach(var item in _inspectionTexts){item.Label.Text=item.Read();if(item.HideEmpty)item.Label.Visible=item.Label.Text.Length>0;}foreach(var item in _inspectionButtons)item.Button.Text=item.Read();foreach(var item in _inspectionTooltips)item.Control.TooltipText=item.Read();return;}
        _inspectionKey=key;_inspectionTexts.Clear();_inspectionButtons.Clear();_inspectionTooltips.Clear();Clear(_inspection);
        if(_selectedBuilding is {} id&&s.Buildings.FirstOrDefault(b=>b.Id==id&&!b.Removed) is {} b){
            _inspector.Visible=true;var summary=Card(_inspection,b.Definition.Name);InspectionText(summary,()=>b.Cause,18);InspectionText(summary,()=>_world.BuildingProblemText(b.Id),16,hideEmpty:true);
            if(b.Kind==BuildingKind.House){var occupants=InspectionText(summary,()=>"Moradores: "+s.Citizens.Count(c=>c.Alive&&c.Resident&&s.Families.Any(f=>f.Id==c.FamilyId&&f.HomeId==b.Id)),18);InspectionTooltip(occupants,()=>"Capacidade de produção/serviço: "+b.OperationalCapacity.ToString("N1")+". Residências abrigam famílias; esse indicador não mede moradores.");}
            else InspectionText(summary,()=>"Capacidade operacional: "+b.OperationalCapacity.ToString("N1"),18);
            if(b.Definition.Utility)ServiceInspection(_inspection,b);
            var infrastructure=Card(_inspection,"Água e energia");
            InspectionText(infrastructure,()=>b.WaterDemand>0?"Água: "+b.WaterRatio.ToString("P0")+" da demanda atendida":"Água: sem demanda atual",14);
            InspectionText(infrastructure,()=>b.ElectricityDemand>0?"Energia: "+b.ElectricityRatio.ToString("P0")+" da demanda atendida":"Energia: sem demanda atual",14);
            InspectionTooltip(infrastructure,()=>"Diagnóstico atual: água "+b.WaterRatio.ToString("P0")+"; energia "+b.ElectricityRatio.ToString("P0"));
            var property=Card(_inspection,"Imóvel");InspectionText(property,()=>"Proprietário: "+AccountName(b.OwnerAccount),14);
            if(b.Definition.Private)InspectionText(property,()=>"Valor de mercado: "+Cash(_sim.MarketValue(b)),14);else InspectionText(property,()=>"Manutenção: "+b.MaintenanceRatio.ToString("P0"),14);
            if(b.Stock.Count>0)InspectionText(_inspection,()=>"Estoque: "+string.Join(" • ",b.Stock.Select(k=>ResourceName(k.Key)+" "+k.Value.ToString("N1"))));
            if(b.Definition.Jobs>0){var staff=Card(_inspection,"Equipe");InspectionText(staff,()=>_sim.WorkersPresent(b)+" presentes no turno · "+s.Citizens.Count(c=>c.Alive&&c.WorkplaceId==b.Id)+" contratados / "+b.Definition.Jobs+" vagas",14);}
            if(!b.Completed&&s.Projects.First(p=>p.Id==b.ProjectId) is {} p){InspectionText(_inspection,()=>"Obra "+p.Progress.ToString("P0")+" • "+p.Cause);InspectionText(_inspection,()=>"Pago "+Cash(p.CostPaid)+" • comprometido "+Cash(p.BudgetRemaining));foreach(var kv in p.Required)InspectionText(_inspection,()=>ResourceName(kv.Key)+": "+p.Delivered.GetValueOrDefault(kv.Key).ToString("N1")+" / "+kv.Value.ToString("N1")+" • reservado "+p.LocalReserved.GetValueOrDefault(kv.Key).ToString("N1"),14);ProjectControls(_inspection,p);}
            if(b.CompanyId is {} co&&s.Companies.FirstOrDefault(c=>c.Id==co) is {} company){InspectionText(_inspection,()=>company.Name,19);InspectionText(_inspection,()=>"Caixa: "+Cash(_sim.Balance(company.Account)));InspectionText(_inspection,()=>company.Decision);InspectionText(_inspection,()=>"Preço: "+Cash(b.SalePrice));}
            foreach(var c in s.Citizens.Where(c=>c.Alive&&c.WorkplaceId==b.Id)){var cid=c.Id;InspectionButton(_inspection,()=>c.Name+" • "+c.Activity,()=>InspectCitizen(cid));}if(b.FamilyId is {} fi&&s.Families.FirstOrDefault(f=>f.Id==fi) is {} family){InspectionText(_inspection,()=>"Despensa: "+family.Pantry.ToString("N1"));foreach(var cid in family.Members){var c=s.Citizens.First(c=>c.Id==cid);var copy=cid;InspectionButton(_inspection,()=>c.Name,()=>InspectCitizen(copy));}}
