        if(_selectedProject is {} projectId&&s.Projects.FirstOrDefault(p=>p.Id==projectId) is {} selectedWork){_inspector.Visible=true;InspectionText(_inspection,()=>(selectedWork.IsMaintenance?"Manutenção #":selectedWork.BuildingId is {} buildingId?s.Buildings.First(building=>building.Id==buildingId).Definition.Name+" · obra #":"Obra viária #")+selectedWork.Id,22);InspectionText(_inspection,()=>selectedWork.Cause+" • "+selectedWork.Progress.ToString("P0"));InspectionText(_inspection,()=>"Pago "+Cash(selectedWork.CostPaid)+" • comprometido "+Cash(selectedWork.BudgetRemaining));foreach(var k in selectedWork.Required)InspectionText(_inspection,()=>ResourceName(k.Key)+" "+selectedWork.Delivered.GetValueOrDefault(k.Key).ToString("N1")+" / "+k.Value.ToString("N1"));ProjectControls(_inspection,selectedWork);return;}
        if(_selectedCitizen is {} ci&&s.Citizens.FirstOrDefault(c=>c.Id==ci) is {} citizen){ShowCitizenInspection(citizen);return;}
        if(_selectedVehicle is {} vi&&s.Vehicles.FirstOrDefault(v=>v.Id==vi) is {} vehicle){_inspector.Visible=true;InspectionText(_inspection,()=>(vehicle.PassengerCar?"Carro particular ":"Caminhão ")+vehicle.Id,22);InspectionText(_inspection,()=>vehicle.Cause);InspectionText(_inspection,()=>"Titular: "+AccountName(vehicle.OwnerAccount));InspectionText(_inspection,()=>"Motorista: "+(vehicle.ExternalDriverId??s.Citizens.FirstOrDefault(c=>c.Id==vehicle.DriverId)?.Name??"aguardando"));InspectionText(_inspection,()=>"Combustível: "+vehicle.Fuel.ToString("N2"));InspectionText(_inspection,()=>"Carga: "+string.Join(" • ",vehicle.Cargo.Select(k=>ResourceName(k.Key)+" "+k.Value.ToString("N1"))));InspectionText(_inspection,()=>"Equipe externa: "+vehicle.CrewCount);return;}
        if(_selectedRoad is {} ri&&s.Roads.FirstOrDefault(r=>r.Id==ri) is {} road){_inspector.Visible=true;InspectionText(_inspection,()=>road.Highway?"Rodovia externa":"Rua 1+1",22);InspectionText(_inspection,()=>"Energia dos postes: "+road.ElectricityRatio.ToString("P0"));InspectionText(_inspection,()=>"Manutenção: "+road.MaintenanceRatio.ToString("P0"));if(!road.Highway&&road.Neighbours.Count>=3)foreach(var control in Enum.GetValues<JunctionControl>()){var ctl=control;InspectionButton(_inspection,()=>ctl switch{JunctionControl.Signal=>"Semáforo",JunctionControl.ThroughX=>"Preferência horizontal",JunctionControl.ThroughZ=>"Preferência vertical",_=>"Preferência à direita"},()=>_sim.SetJunction(road.Id,ctl));}if(!road.Highway)InspectionButton(_inspection,()=>"× Remover trecho",()=>ShowRoadDemolition(road.Id));return;}
        _inspector.Visible=false;
    }
    void ProjectControls(Node parent,WorkProject project){if(project.MachineryQuoted>0){InspectionText(parent,()=>"Máquinas externas · previsto "+Cash(project.MachineryQuoted)+" · pago "+Cash(project.MachineryPaid),14);}if(project.IsMaintenance){Text(parent,"Manutenção automática; materiais e equipe municipal ou externa têm execução real.",14);return;}if(project.Status is not (WorkStatus.Waiting or WorkStatus.InProgress))return;InspectionText(parent,()=>"Cancelar libera "+Cash(Math.Max(0,project.BudgetRemaining-decimal.Round(project.CrewCostDue,2,MidpointRounding.AwayFromZero)))+"; gastos pagos/devidos ("+Cash(project.CostPaid+decimal.Round(project.CrewCostDue,2,MidpointRounding.AwayFromZero))+") e materiais entregues/consumidos não voltam.",14);Button(parent,"× Cancelar obra",()=>{_sim.CancelProject(project.Id);RefreshHud();});Button(parent,"↗ Mover obra",()=>BeginMove(project));}
    void ShowRoadDemolition(int roadId,string feedback="")
    {
        var quote=_sim.QuoteRoadDemolition(roadId);var box=Modal("Remover trecho de rua");if(feedback.Length>0)Text(box,feedback,16);
        if(!quote.Allowed){Text(box,quote.Message);var refused=ModalActions();Button(refused,"× Cancelar",CloseModal);return;}
        Text(box,"Custo de remoção: "+Cash(quote.Cost),22);
        Text(box,"Indenização: não se aplica a esta rua municipal",14);
        Text(box,"Total: "+Cash(quote.Cost),18);
        Text(box,"Caixa disponível: "+Cash(_sim.Available),14);
        Text(box,"Retirada imediata após confirmar. Sem reembolso de dinheiro ou materiais.",14);
        Text(box,quote.Message);
        Text(box,"Construções que perderão conexão exterior: "+quote.IsolatedBuildingIds.Count);
        foreach(var id in quote.IsolatedBuildingIds){var building=_sim.State.Buildings.First(b=>b.Id==id);Text(box,building.Definition.Name+" • "+building.Position.X.ToString("N0")+", "+building.Position.Z.ToString("N0"),14);}
        Text(box,"Obras com acesso interrompido: "+quote.InterruptedWorks+" • rotas atuais pelo trecho: "+quote.AffectedVehicleRoutes,14);
        if(quote.Cost>_sim.Available)Text(box,"Caixa livre insuficiente: falta "+Cash(quote.Cost-_sim.Available)+" para confirmar. Libere reservas ou aumente o Caixa.",14);
        var row=ModalActions();var confirm=Button(row,"✓ Confirmar remoção",()=>ConfirmRoadDemolition(roadId,quote,box));confirm.Disabled=!quote.Allowed||quote.Cost>_sim.Available;Button(row,"× Cancelar",CloseModal);
    }
    void InspectCitizen(int id){ClearSelection();ClearTool();_selectedCitizen=id;_selectedBuilding=null;_selectedVehicle=null;_selectedRoad=null;RefreshInspection();CloseModal();}
    static string ResourceName(ResourceKind r)=>r switch{ResourceKind.Aggregate=>"Areia e brita",ResourceKind.Concrete=>"Concreto",ResourceKind.Steel=>"Aço",ResourceKind.Wood=>"Madeira",ResourceKind.Asphalt=>"Asfalto",ResourceKind.Food=>"Alimentos",_=>"Combustível"};
    VBoxContainer Modal(string title)
    {
        CloseModal();HideAlertTooltip();var viewport=GetViewport().GetVisibleRect().Size;var width=(int)Math.Min(720,viewport.X-64);var height=(int)Math.Min(600,viewport.Y-72);_modal=new Window{Title=title,Size=new(width,height),MinSize=new(420,220),Transient=true,Exclusive=true,Unresizable=false};AddChild(_modal);_modal.CloseRequested+=CloseModal;
        var layout=new VBoxContainer();layout.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);layout.OffsetLeft=16;layout.OffsetTop=16;layout.OffsetRight=-16;layout.OffsetBottom=-16;_modal.AddChild(layout);var heading=new HBoxContainer();layout.AddChild(heading);Text(heading,title,22);var close=Button(heading,"× Fechar",CloseModal,"Fechar janela");close.CustomMinimumSize=new(104,40);close.AutowrapMode=TextServer.AutowrapMode.Off;close.SizeFlagsHorizontal=Control.SizeFlags.Fill;
        var scroll=new ScrollContainer{HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled,SizeFlagsVertical=Control.SizeFlags.ExpandFill,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};layout.AddChild(scroll);var box=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};box.AddThemeConstantOverride("separation",8);scroll.AddChild(box);_modal.PopupCentered();FitModal(_modal,box);return box;
    }
    async void FitModal(Window window,VBoxContainer body)
    {
        await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);if(_modal!=window||!GodotObject.IsInstanceValid(window))return;var viewport=GetViewport().GetVisibleRect().Size;var wanted=(int)Math.Ceiling(body.GetCombinedMinimumSize().Y+100+(window.FindChild("ModalActions",true,false)!=null?48:0));window.Size=new(window.Size.X,Math.Clamp(wanted,220,(int)viewport.Y-72));window.PopupCentered();
    }
    void CloseModal(){HideAlertTooltip();if(_modal!=null){_modal.Hide();_modal.QueueFree();_modal=null;}}
}
